new='double te=c.optDouble("temperature_2m",Double.NaN),pr=c.optDouble("precipitation",0),cl=c.optDouble("cloud_cover",0),hu=c.optDouble("relative_humidity_2m",Double.NaN),wi=c.optDouble("wind_speed_10m",Double.NaN);int wc=c.optInt("weather_code",-1);String ws=pr>=.1?t("अहिले वर्षा भइरहेको छ","Rain now"):t("अहिले वर्षा छैन","No rain now");String timing=rainTiming(j);String cond=weatherCodeLabel(wc);currentWeather=t(cond+", तापक्रम "+(Double.isFinite(te)?Math.round(te)+"°C":"उपलब्ध छैन")+", वर्षा "+String.format(Locale.US,"%.1f",pr)+" mm, बादल "+Math.round(cl)+"%"+(Double.isFinite(hu)?", आर्द्रता "+Math.round(hu)+"%":"")+(Double.isFinite(wi)?", हावा "+Math.round(wi)+" km/h":"")+"।",cond+", "+(Double.isFinite(te)?Math.round(te)+"°C":"temperature unavailable")+", rain "+String.format(Locale.US,"%.1f",pr)+" mm, cloud "+Math.round(cl)+"%"+(Double.isFinite(hu)?", humidity "+Math.round(hu)+"%":"")+(Double.isFinite(wi)?", wind "+Math.round(wi)+" km/h":"")+".");'
