# Add helpers immediately before answerSathi generated by v0.9.10.
anchor='    private String answerSathi(String q){'
if anchor not in s: raise SystemExit('answerSathi anchor missing')
helpers=r'''    // V0916_SATHI_DISTRICT_WEATHER — district-specific answers use live current weather at the district geometry centre.
    private void submitSathiQuestion(TextView out,ScrollView chatScroll,String q){
        if(isWeatherQuestion(q)){
            io.execute(()->{
                String a=null;
                try{a=districtWeatherAnswer(q);}catch(Exception ignored){}
                final String answer=(a==null||a.isEmpty())?answerSathi(q):a;
                runOnUiThread(()->{appendSathiTurn(out,chatScroll,q,answer);speak(answer);});
            });
        }else{String a=answerSathi(q);appendSathiTurn(out,chatScroll,q,a);speak(a);}
    }

    private boolean isWeatherQuestion(String q){String x=q==null?"":q.toLowerCase(Locale.ROOT);return x.contains("weather")||x.contains("mausam")||x.contains("मौसम")||x.contains("rain")||x.contains("pani")||x.contains("पानी")||x.contains("वर्षा")||x.contains("temperature")||x.contains("temp")||x.contains("garmi")||x.contains("chiso")||x.contains("cloud")||x.contains("बादल")||x.contains("तापक्रम")||x.contains("aaja")||x.contains("आज");}

    private String districtWeatherAnswer(String q)throws Exception{
        JSONObject root=assetJson("floodsafe-nepal/v24/nepal-districts.geojson");JSONArray fs=root.optJSONArray("features");if(fs==null)return null;String low=q==null?"":q.toLowerCase(Locale.ROOT);JSONObject hit=null;String name="";
        for(int i=0;i<fs.length();i++){JSONObject f=fs.optJSONObject(i);if(f==null)continue;String n=f.optJSONObject("properties")==null?"":f.optJSONObject("properties").optString("nameEn","").trim();if(n.isEmpty())continue;String key=n.toLowerCase(Locale.ROOT);if(low.matches(".*(^|[^a-z])"+java.util.regex.Pattern.quote(key)+"([^a-z]|$).*")||low.contains(key)){hit=f;name=n;break;}}
        if(hit==null)return null;JSONObject geo=hit.optJSONObject("geometry");if(geo==null)return null;double[] b={Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY};scanGeoBounds(geo.optJSONArray("coordinates"),b);if(!Double.isFinite(b[0])||!Double.isFinite(b[1])||!Double.isFinite(b[2])||!Double.isFinite(b[3]))return null;double a=(b[0]+b[1])/2d,o=(b[2]+b[3])/2d;
        String u=String.format(Locale.US,"https://api.open-meteo.com/v1/forecast?latitude=%.5f&longitude=%.5f&current=temperature_2m,relative_humidity_2m,precipitation,cloud_cover,weather_code,wind_speed_10m&timezone=Asia%%2FKathmandu",a,o);JSONObject c=getJson(u).optJSONObject("current");if(c==null)return null;double te=c.optDouble("temperature_2m",Double.NaN),pr=c.optDouble("precipitation",0),cl=c.optDouble("cloud_cover",0),hu=c.optDouble("relative_humidity_2m",Double.NaN),wi=c.optDouble("wind_speed_10m",Double.NaN);int wc=c.optInt("weather_code",-1);String cond=weatherCodeLabel(wc);boolean tempOnly=low.contains("temperature")||low.contains("temp")||low.contains("तापक्रम")||low.contains("garmi")||low.contains("chiso");
        if(tempOnly)return t(name+" को तापक्रम "+(Double.isFinite(te)?Math.round(te)+"°C":"उपलब्ध छैन")+" छ · "+cond+"।",name+" temperature is "+(Double.isFinite(te)?Math.round(te)+"°C":"unavailable")+" · "+cond+".");
        return t(name+": "+cond+", तापक्रम "+(Double.isFinite(te)?Math.round(te)+"°C":"उपलब्ध छैन")+", वर्षा "+String.format(Locale.US,"%.1f",pr)+" mm, बादल "+Math.round(cl)+"%"+(Double.isFinite(hu)?", आर्द्रता "+Math.round(hu)+"%":"")+(Double.isFinite(wi)?", हावा "+Math.round(wi)+" km/h":"")+"।",name+": "+cond+", "+(Double.isFinite(te)?Math.round(te)+"°C":"temperature unavailable")+", rain "+String.format(Locale.US,"%.1f",pr)+" mm, cloud "+Math.round(cl)+"%"+(Double.isFinite(hu)?", humidity "+Math.round(hu)+"%":"")+(Double.isFinite(wi)?", wind "+Math.round(wi)+" km/h":"")+".");
    }
    private void scanGeoBounds(JSONArray a,double[] b){if(a==null)return;if(a.length()>=2&&a.opt(0) instanceof Number&&a.opt(1) instanceof Number){double o=a.optDouble(0,Double.NaN),la=a.optDouble(1,Double.NaN);if(Double.isFinite(la)&&Double.isFinite(o)){b[0]=Math.min(b[0],la);b[1]=Math.max(b[1],la);b[2]=Math.min(b[2],o);b[3]=Math.max(b[3],o);}return;}for(int i=0;i<a.length();i++){Object x=a.opt(i);if(x instanceof JSONArray)scanGeoBounds((JSONArray)x,b);}}
    private String weatherCodeLabel(int c){if(c==0)return t("खुला आकाश","Clear");if(c==1)return t("मुख्यतः खुला","Mostly clear");if(c==2)return t("आंशिक बादल","Partly cloudy");if(c==3)return t("बादल","Overcast");if(c==45||c==48)return t("कुहिरो","Fog");if(c>=51&&c<=57)return t("झरी","Drizzle");if(c>=61&&c<=67)return t("वर्षा","Rain");if(c>=71&&c<=77)return t("हिमपात","Snow");if(c>=80&&c<=82)return t("वर्षा shower","Rain showers");if(c>=95&&c<=99)return t("मेघगर्जन","Thunderstorm");return t("मौसम","Weather");}

'''
s=s.replace(anchor,helpers+anchor,1)

# Add gyan/fact handling before generic weather branch in the conversational answer.
