# Replace empty 30-minute news result with rotating knowledge fallback.
pat=re.compile(r'private void renderNews\(List<NewsItem> out\)\{newsList\.removeAllViews\(\);if\(out\.isEmpty\(\)\)\{newsList\.addView\(empty\(t\("नयाँ live समाचार भेटिएन।","No fresh live stories found\."\)\)\);return;\}')
m=pat.search(s)
if not m: raise SystemExit('renderNews empty branch missing')
s=s[:m.start()]+m.group(0).replace('newsList.addView(empty(t("नयाँ live समाचार भेटिएन।","No fresh live stories found.")));return;','renderKnowledgeFallback(true);return;')+s[m.end():]

